import itertools

def solve():
    n = 7
    edges = list(itertools.combinations(range(n), 2))
    fixed_edges = [(0, 6), (1, 5)]

    # We can use a simple backtracking approach
    # State: list of edges

    def is_triangle_free(adj):
        for i in range(n):
            for j in range(i+1, n):
                if adj[i][j]:
                    for k in range(j+1, n):
                        if adj[j][k] and adj[i][k]:
                            return False
        return True

    def is_maximal(adj):
        for i in range(n):
            for j in range(i+1, n):
                if not adj[i][j]:
                    # Check if adding (i, j) creates a triangle
                    # i.e., check if they share a common neighbor
                    shared = False
                    for k in range(n):
                        if adj[i][k] and adj[j][k]:
                            shared = True
                            break
                    if not shared:
                        return False
        return True

    # Let's use PySAT
    from pysat.solvers import Glucose3
    solver = Glucose3()

    # Variables for edges
    edge_vars = {}
    var_idx = 1
    for u, v in edges:
        edge_vars[(u, v)] = var_idx
        var_idx += 1

    # Fixed edges
    for u, v in fixed_edges:
        solver.add_clause([edge_vars[(u, v)]])

    # Triangle-free constraints
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                solver.add_clause([-edge_vars[(i, j)], -edge_vars[(j, k)], -edge_vars[(i, k)]])

    # Maximal constraints: for any non-edge (u, v), there must be a common neighbor w
    # So edge(u, v) OR (edge(u, w1) AND edge(v, w1)) OR ...
    # This means edge(u, v) OR OR_w (edge(u, w) AND edge(v, w))
    # We can introduce auxiliary variables for (edge(u, w) AND edge(v, w))
    for u in range(n):
        for v in range(u+1, n):
            clause = [edge_vars[(u, v)]]
            for w in range(n):
                if w != u and w != v:
                    # aux = edge(u, w) AND edge(v, w)
                    aux = var_idx
                    var_idx += 1
                    e1 = edge_vars[(min(u, w), max(u, w))]
                    e2 = edge_vars[(min(v, w), max(v, w))]
                    # aux <=> e1 AND e2
                    # aux -> e1
                    solver.add_clause([-aux, e1])
                    # aux -> e2
                    solver.add_clause([-aux, e2])
                    # e1 AND e2 -> aux
                    solver.add_clause([-e1, -e2, aux])
                    clause.append(aux)
            solver.add_clause(clause)

    if solver.solve():
        model = solver.get_model()
        result = []
        for u, v in edges:
            if model[edge_vars[(u, v)] - 1] > 0:
                result.append((u, v))
        print(result)
    else:
        print("UNSATISFIABLE")

solve()
